 int slab_unmergeable(struct kmem_cache *s)
 {
 	if (slab_nomerge || (s->flags & SLAB_NEVER_MERGE))
 		return 1;

 	if (!is_root_cache(s))
 		return 1;

 	if (s->ctor)
 		return 1;

 	if (s->usersize)
