{
	struct kmem_cache *s;
	char *cache_name;

	get_online_cpus();
	mutex_lock(&slab_mutex);

	/*
	 * Since per-memcg caches are created asynchronously on first
	 * allocation (see memcg_kmem_get_cache()), several threads can try to
